  _ = `Republicar`,
  _ = `Republicar significa fazer referência do evento da Central de Notícias no feed dos grupos escolhidos abaixo. Os seguintes são outros grupos da comunidade ou aplicações nos quais este evento pode ser republicado. Escolha um ou mais grupos onde publicar.`,
