  _ = `É necessária uma análise da Valve para que esta página seja publicada`,
  _ = `Este evento promocional está a aguardar por aprovação da Valve`,
  _ = `Use o botão à direita para enviar a sua página para análise com, pelo menos, sete dias de antecedência da data de publicação pretendida para garantir que haverá tempo para rever/aprovar quaisquer alterações necessárias.`,
  _ = `A equipa do Steam entrará em contacto consigo através do pedido à equipa de apoio do Steamworks se for necessário efetuar alterações à sua página. Clique no botão à direita para consultar o pedido e adicionar comentários, se necessário.`,
  _ = `Marcar a página como aprovada permitirá ao parceiro publicá-la para ficar online.`,
  _ = `Solicitar análise...`,
  _ = `Solicitar análise`,
  _ = `Esta ação irá enviar a solicitação de uma análise da aprovação da publicação da página de promoção. Solicite a análise quando a sua página promocional tiver os recursos gráficos finais e incluir todos os jogos que pretende destacar.`,
  _ = `Esta ação irá enviar um pedido à equipa de apoio do Steamworks a solicitar uma análise da sua página de promoção por parte da Valve. Recomendamos que apenas solicite a análise quando os recursos gráficos, as mensagens e a lista de jogos estiverem finalizados.`,
  _ = `Certifique-se de que o título e a finalidade do seu evento são descritos com clareza perto do topo da página. Caso se trate de uma apresentação (Showcase), pode precisar de uma secção de texto no topo da sua página para descrever o evento e como funciona.`,
  _ = `A página de promoção será bloqueada assim que for analisada. Se pretende efetuar alterações após a análise ou assim que o evento começar, comente essas alterações e por que motivo não puderam ser efetuadas antes da análise.`,
  _ = `Opcional: informações que pretende incluir para a equipa de análise`,
  _ = `Escolha os parceiros cujos membros também podem aceder à solicitação`,
  _ = `Opcional: se escolher esta opção, outros membros dos parceiros podem aceder e responder à solicitação. Por predefinição, apenas você pode ler, atualizar e responder à solicitação criada.`,
  _ = `Não foi possível criar a solicitação. Tente mais tarde.`,
