  _ = `Pré-visualizar revelação dinâmica`,
  _ = `A secção abaixo foi definida para usar a funcionalidade de revelação dinâmica. Para pré-visualizar a funcionalidade, inicie o teste. A secção irá voltar ao estado inicial assim que sair do separador de pré-visualização.`,
