  _ = `Nomear este jogo para "%1$s"`,
  _ = `Nomeaste este jogo para "%1$s"`,
  _ = `Jogo do Ano`,
  _ = `Jogo de R.V. do Ano`,
  _ = `Feito Com Amor`,
  _ = `Melhor Com Amigos`,
  _ = `Estilo Visual Excecional`,
  _ = `Jogabilidade Mais Inovadora`,
  _ = `Melhor Jogo Que Jogas Mal`,
  _ = `Melhor Banda Sonora`,
  _ = `História Excecional`,
  _ = `Mais Relaxante`,
  _ = `Não sugira uma categoria específica e, em vez disso, deixe os seus fãs selecionar a categoria que eles acharem mais apropriada para o seu jogo. O evento irá incluir mesmo assim um link para a página de nomeações.`,
  _ = `Sem categoria`,
  _ = `Talvez o ponto forte deste jogo seja uma jogabilidade envolvente ou uma história cativante. Ou então o facto de ter personagens complexas, um estilo impecável ou até um modo multijogador viciante. Seja qual for o motivo, o vencedor do prémio de Jogo do Ano 2020 é um clássico imediato.`,
  _ = `O jogo de R.V. do ano não está meramente a fazer‑se passar por uma realidade normal. Este jogo aperfeiçoa a realidade, tirando partido deste meio e ultrapassando os limites da realidade virtual.`,
  _ = `Este jogo já saiu há uns tempos. Já lá vão os dias em que os criadores deste jogo anunciaram a estreia do seu bebé criativo, mas como bons pais que são, continuaram a desenvolver e a apoiar a sua criação. Este jogo, atualmente, ainda recebe conteúdo novo mesmo após estes anos todos.`,
  _ = `Há jogos que simplesmente não são a mesma coisa quando os jogas a sós. Talvez precises de um amigo para encher os inimigos de porrada. Talvez precises de um amigo para que sejas tu a enchê-lo de porrada. De qualquer das formas, montes de diversão esperam quem jogar este jogo em boa companhia.`,
  _ = `Estilo visual não significa necessariamente uma representação gráfica fiel do mundo real (apesar de isto ser um objetivo respeitável), mas sim um olhar e uma sensação distintos que abrangem o jogo inteiro.`,
  _ = `Os criadores deste jogo estão na vanguarda da experimentação, oferecendo perspetivas novas e surpresas alucinantes. Este jogo encantou, inspirou e entreteve com os seus elementos inéditos.`,
  _ = `Este é o jogo que recompensa a persistência. Não é para todos. É o jogo mais difícil que alguma vez amámos.`,
  _ = `O vencedor deste prémio merece ser reconhecido pela sua música excecional. É a banda sonora para toda a hora! `,
  _ = `Há dias em que só apetece jogar um jogo com uma história envolvente, e este até deixa a chorar por mais. É tão cativante como qualquer novela e tão refinado como um guião de uma grande série de TV. Bravo, bravíssimo – por nos deixarem emocionados!`,
  _ = `Este jogo é o melhor remédio para um dia cansativo. É calmo, é relaxante, ajuda-te a esquecer das preocupações. Este jogo é o teu momento zen.`,
  _ = `Alterar a tua nomeação?`,
  _ = `Só podes nomear um jogo para cada categoria e já nomeaste %1$s para esta. Gostarias de nomear %2$s em vez desse?`,
  _ = `Votar`,
  _ = `Já votaste`,
  _ = `Voto enviado`,
  _ = `Alterar o voto?`,
  _ = `Só podes votar num jogo por categoria e já votaste em %1$s nesta. Gostarias de mudar o teu voto para %2$s?`,
  _ = `A tua conta parece ser limitada. Para impedir abuso de nomeações, terás de gastar 5\xA0$\xA0USD (ou o equivalente regional) no Steam para poderes participar nos Prémios Steam. %1$s para mais informações.`,
  _ = `A tua conta parece ser limitada. Para impedir abuso de votos, terás de gastar 5\xA0$\xA0USD (ou o equivalente regional) no Steam para poderes participar nos Prémios Steam. %1$s para mais informações.`,
  _ = `Jogo do Ano`,
  _ = `Jogo de R.V. do Ano`,
  _ = `Feito Com Amor`,
  _ = `Melhor Com Amigos`,
  _ = `Estilo Visual Excecional`,
  _ = `Jogabilidade Mais Inovadora`,
  _ = `Melhor Jogo Que Jogas Mal`,
  _ = `Melhor Banda Sonora`,
  _ = `História Excecional`,
  _ = `Mais Relaxante`,
  _ = `Talvez o ponto forte deste jogo seja uma jogabilidade envolvente ou uma história cativante. Ou então o facto de ter personagens complexas, um estilo impecável ou até um modo multijogador viciante. Seja qual for o motivo, o vencedor do prémio de melhor jogo deste ano é um clássico imediato.`,
  _ = `O jogo de R.V. do ano não está meramente a fazer‑se passar por uma realidade normal. Este jogo aperfeiçoa a realidade, tirando partido deste meio e ultrapassando os limites da realidade virtual.`,
  _ = `Este jogo já saiu há uns tempos. Já lá vão os dias em que os criadores deste jogo anunciaram a estreia do seu bebé criativo, mas como bons pais que são, continuaram a desenvolver e a apoiar a sua criação. Este jogo, atualmente, ainda recebe conteúdo novo mesmo após estes anos todos.`,
  _ = `Há jogos que simplesmente não são a mesma coisa quando os jogas a sós. Talvez precises de um amigo para encher os inimigos de porrada. Talvez precises de um amigo para que sejas tu a enchê-lo de porrada. De qualquer das formas, montes de diversão esperam quem jogar este jogo em boa companhia.`,
  _ = `Estilo visual não significa necessariamente uma representação gráfica fiel do mundo real (apesar de isto ser um objetivo respeitável), mas sim um olhar e uma sensação distintos que abrangem o jogo inteiro.`,
  _ = `Os criadores deste jogo estão na vanguarda da experimentação, oferecendo perspetivas novas e surpresas alucinantes. Este jogo encantou, inspirou e entreteve com os seus elementos inéditos.`,
  _ = `Este é o jogo que recompensa a persistência. Não é para todos. É o jogo mais difícil que alguma vez amámos.`,
  _ = `O vencedor deste prémio merece ser reconhecido pela sua música excecional. É a banda sonora para toda a hora! `,
  _ = `Há dias em que só apetece jogar um jogo com uma história envolvente, e este até deixa a chorar por mais. É tão cativante como qualquer novela e tão refinado como um guião de uma grande série de TV. Bravo, bravíssimo – por nos deixarem emocionados!`,
  _ = `Este jogo é o melhor remédio para um dia cansativo. É calmo, é relaxante, ajuda-te a esquecer das preocupações. Este jogo é o teu momento zen.`,
