  _ = `A GRANDE CORRIDA DO IMPERADOR`,
  _ = `A origem do horóscopo chinês`,
  _ = `Parte I de IV`,
  _ = `Parte II de IV`,
  _ = `Parte III de IV`,
  _ = `Parte IV de IV`,
  _ = `O Imperador de Jade convocou todas as criaturas do seu domínio para que participassem numa corrida até ao seu palácio divino, declarando que os doze primeiros a chegar receberiam a honra de ter um lugar no seu novo calendário.

O esperto Rato foi o primeiro a atravessar o rio para chegar ao plano celestial. Como nadar não era o seu forte, aproveitou para ir de boleia às costas do fiel Boi, saltando entusiasmadamente para o jardim do Imperador mesmo antes do par chegar à margem.

O Boi, devagarinho mas sem hesitação, conseguiu facilmente atravessar o rio. Despreocupado com os resultados da corrida, o Boi ficou contente pelo seu papel na vitória do Rato.`,
  _ = `O hábil Tigre viajou de forma tão cuidadosa que não conseguiu ultrapassar o Boi, concluindo que mais vale acabar em terceiro do que não acabar sequer a corrida.

O ágil Coelho saltou para um tronco a flutuar na água que depressa perdeu o seu rumo. Contudo, a sorte compensou-o pela sua falta de estratégia, graças a uma lufada de vento que soprou e guiou o barco improvisado, em segurança, até ao seu destino.

O alado Dragão viu dos céus uma aldeia em apuros e claro que teve de parar para ajudar — acabando até por oferecer a lufada de ar que guiou o Coelho. A honra é algo mais importante do que a vitória, e o Dragão achou que o quinto lugar era justamente merecido.`,
  _ = `A sorrateira Serpente estava pouco interessada em fazer grandes esforços, por isso decidiu enrolar-se discretamente à volta da pata dianteira do Cavalo.

Enquanto o Cavalo galopava até à meta, a Serpente desenrolou-se, assustando o corcel durante tempo suficiente para deslizar até ao sexto lugar — com o nervoso Cavalo a trotar logo atrás.`,
  _ = `A Cabra, o Macaco e o Galo trabalharam em equipa, mas deixaram a Cabra ficar em oitavo lugar pelo seu papel fundamental durante a jornada. O alegre Macaco veio a seguir e o pavoneante Galo ficou em décimo, orgulhoso da ordem de chegada tão justa.

Já o Cão, muito brincalhão, estava mais interessado em chapinhar por lá e achou que o décimo primeiro lugar era uma boa troca pelo tempo que passou a divertir-se.

Em último chegou o Porco, que tinha parado para um lanche e uma sesta, sendo sábio o suficiente para saber que cada um dos animais terá igual oportunidade para receber as graças do Imperador.`,
  _ = `As alterações ao perfil entrarão em efeito após análise`,
