  Vde = `Uma troca foi revertida`,
  Hde = `Uma troca foi revertida`,
  Ude = `Uma das tuas trocas recentes foi revertida pela pessoa com quem trocaste.`,
  Wde = `Dados anónimos da taxa de frames:`,
  Gde = `Podemos recolher dados anónimos da taxa de frames enquanto jogas na tua conta Steam? Estes dados ajudam-nos a melhorar a compatibilidade de jogos e o Steam.`,
  Kde = `Dados anónimos da taxa de frames`,
  qde = `Se aceitares, os dados de taxas de frames serão armazenados sem nenhuma associação à tua conta Steam, mas serão identificados com base no tipo de hardware que estiveres a usar para jogar. Estes dados ajudam-nos a obter mais informações sobre a compatibilidade de jogos e a melhorar a experiência em dispositivos com Steam.`,
  Jde = `Podes alterar esta definição mais tarde nas definições da tua conta Steam`,
  Yde = `Saber mais`,
  Xde = `Compatibilidade com o Steam Deck`,
  Zde = `Steam Deck Verified - Feedback dos utilizadores`,
  Qde = `Sem dados disponíveis`,
  $de = `%1$s dos inquiridos concordam com a classificação "%2$s" deste jogo. Para comparação, cerca de 95% dos inquiridos concordam com a classificação de jogos "Aprovados" para o Steam Deck.`,
  efe = `%1$s%`,
  tfe = `Estamos a partilhar estes dados porque, embora a grande maioria dos utilizadores inquiridos concorde com a classificação "Aprovado" dos jogos (>95%), pode ser muito útil ter uma melhor perceção da experiência dos utilizadores que discordam, particularmente no contexto de uma atualização ou produto específico.`,
  nfe = `Desempenho`,
  rfe = `Legibilidade`,
  ife = `Estabilidade`,
  afe = `Controlos`,
  ofe = `Outros`,
  sfe = `Estes dados são baseados em %1$s relatórios nos últimos %2$s dias de utilizadores que aceitaram partilhar feedback no Steam Deck.`,
  cfe = `Os utilizadores que %1$s com a classificação "%2$s" do jogo partilharam os seguintes motivos pelos quais não concordaram.`,
  lfe = `não concordaram`,
  ufe = `Taxa de frames média no Steam Deck`,
  dfe = `A taxa de frames média relatada para %1$s no dispositivo "%2$s" é de %3$s`,
  ffe = `A taxa de frames média relatada para este jogo no dispositivo "%1$s" é de %2$s`,
  pfe = `%1$s FPS`,
  mfe = `Estes dados são baseados em relatórios da taxa de frames dos últimos %1$s dias de utilizadores que aceitaram partilhar dados da taxa de frames.`,
  hfe = `Atenção: os dados de variância não estão disponíveis de momento, mas serão mostrados ainda durante a fase beta. Com estes dados, poderás ver se a taxa de frames é estável ou se varia significativamente.`,
  gfe = `Motivo`,
  _fe = `N.º de respostas`,
  vfe = `Os dados do histograma são baseados em relatórios da taxa de frames do %1$s que foram fornecidos por utilizadores do dispositivo %2$s que aceitaram partilhar dados da taxa de frames.`,
  yfe = `Os dados do histograma são baseados em relatórios da taxa de frames deste jogo que foram fornecidos por utilizadores do dispositivo %1$s que aceitaram partilhar dados da taxa de frames.`,
  bfe = `Distribuição da taxa de frames`,
